# Create dataset for survival analysis with time-dependent covariate
# Gill-Anderson model
#
x <- data.frame(onset=c(46, 32, 53, 76, 64, 43),
                case=c(1,1,1,0,0,0),
                ooph=c(NA, 30, 38, 50, NA, NA),
                ocp=c(1,1,0,0,1,0),
